window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-18ee59a76295c37a"]={"versions": [{"id": "FIG-18ee59a76295c37a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext des AUTOSAR Virtual Function Bus (VFB). Es veranschaulicht das grundlegende Architekturmuster einer 1:1-Client-Server-Beziehung zwischen zwei Software-Komponenten (SW-C).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Client</strong>: Software-Komponente, die über einen Required-Port (dargestellt als Socket- bzw. Halbkreis-Symbol an der rechten Begrenzung) Operationen anfordert.\n</li><li><strong>Server</strong>: Software-Komponente, die über einen Provided-Port (dargestellt als Ball- bzw. Kreis-Symbol an der linken Begrenzung) Dienste bzw. Operationen bereitstellt.\n</li><li><strong>Assembly-Konnektor</strong>: Verbindungslinie zwischen dem Required-Port des Clients und dem Provided-Port des Servers zur Übertragung des Operationsaufrufs und der Ergebnisrückgabe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner oder synchroner Funktionsaufruf: Der Client initiiert die Kommunikation durch Aufruf einer Operation am Server. Der Server führt die angeforderte Logik aus und liefert gegebenenfalls Rückgabewerte oder Statuscodes an den aufrufenden Client zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Grundlegendes Kommunikationsparadigma gemäß VFB-Spezifikation für nachfragegesteuerte Interaktionen (Methoden-/Funktionsaufrufe) im Unterschied zum datenzentrierten Sender-Receiver-Paradigma. Typischerweise auf Schnittstellenebene über <code>ClientServerInterface</code> mit darin deklarierten <code>Operations</code> und Argumenten realisiert.</p>"}, {"id": "FIG-744c660ee72afa20", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext des AUTOSAR Virtual Function Bus (VFB). Es veranschaulicht das grundlegende Architekturmuster einer 1:1-Client-Server-Beziehung zwischen zwei Software-Komponenten (SW-C).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Client</strong>: Software-Komponente, die über einen Required-Port (dargestellt als Socket- bzw. Halbkreis-Symbol an der rechten Begrenzung) Operationen anfordert.\n</li><li><strong>Server</strong>: Software-Komponente, die über einen Provided-Port (dargestellt als Ball- bzw. Kreis-Symbol an der linken Begrenzung) Dienste bzw. Operationen bereitstellt.\n</li><li><strong>Assembly-Konnektor</strong>: Verbindungslinie zwischen dem Required-Port des Clients und dem Provided-Port des Servers zur Übertragung des Operationsaufrufs und der Ergebnisrückgabe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner oder synchroner Funktionsaufruf: Der Client initiiert die Kommunikation durch Aufruf einer Operation am Server. Der Server führt die angeforderte Logik aus und liefert gegebenenfalls Rückgabewerte oder Statuscodes an den aufrufenden Client zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Grundlegendes Kommunikationsparadigma gemäß VFB-Spezifikation für nachfragegesteuerte Interaktionen (Methoden-/Funktionsaufrufe) im Unterschied zum datenzentrierten Sender-Receiver-Paradigma. Typischerweise auf Schnittstellenebene über <code>ClientServerInterface</code> mit darin deklarierten <code>Operations</code> und Argumenten realisiert.</p>"}], "trans": [{"from": "FIG-18ee59a76295c37a", "to": "FIG-744c660ee72afa20", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
